import { LOGO_NEEDLE, LOGO_STITCHES, LOGO_THREAD, LOGO_THREAD_WIDTH, LOGO_VIEWBOX } from "@/lib/logo-geometry";

/**
 * The Threadcore mark: a "T" made from a needle and thread. The thread passes
 * through the needle's eye and continues as running stitches. Geometry is
 * generated by scripts/generate-logo.mjs.
 */
export function LogoMark({
  className,
  tone = "dark",
}: {
  className?: string;
  /** "dark" = for light backgrounds, "light" = for dark backgrounds. */
  tone?: "dark" | "light";
}) {
  const needle = tone === "dark" ? "var(--ink)" : "#ffffff";
  const thread = tone === "dark" ? "var(--brand-accent)" : "#ff6a47";
  return (
    <svg viewBox={LOGO_VIEWBOX} aria-hidden="true" className={className}>
      {/* The thread is drawn first so it shows through the needle's eye. */}
      <g fill="none" stroke={thread} strokeWidth={LOGO_THREAD_WIDTH} strokeLinecap="round">
        <path d={LOGO_THREAD} />
        <path d={LOGO_STITCHES} />
      </g>
      <path d={LOGO_NEEDLE} fill={needle} fillRule="evenodd" />
    </svg>
  );
}
